def card(label: str, title: str, text: str) -> dict[str, str]:
    return {"label": label, "title": title, "text": text}


def table(title: str, columns: list[str], rows: list[list[object]]) -> dict[str, object]:
    return {"title": title, "columns": columns, "rows": rows}


def section(title: str, *, content: list[str] | None = None, data_table: dict[str, object] | None = None) -> dict[str, object]:
    result: dict[str, object] = {"title": title}
    if content:
        result["content"] = content
    if data_table:
        result["table"] = data_table
    return result


def build_lab(
    *,
    number: int,
    semester: int,
    semester_lab_number: int,
    title: str,
    points: int,
    practical_result: str,
    situation: str,
    goal: str,
    outcomes: list[str],
    tools: list[str],
    theory: list[dict[str, str]],
    source_sections: list[dict[str, object]],
    task: list[str],
    stages: list[str],
    deliverables: list[str],
    evidence: list[str],
    self_check: list[str],
    professional_choice: str,
) -> dict[str, object]:
    block = 1 if semester == 7 else 2
    block_title = "Организация сопровождения и работа службы поддержки" if block == 1 else "Выявление и устранение отказов информационной системы"
    topic_code = "06.02.1" if block == 1 else "06.02.2"
    slug = f"{semester}-{semester_lab_number:02d}"
    report_file = f"S{semester}_LR{semester_lab_number:02d}_template.docx"
    sequence_input, sequence_output = SEQUENCE[number]
    return {
        "number": number,
        "semesterLabNumber": semester_lab_number,
        "slug": slug,
        "title": title,
        "block": block,
        "blockTitle": block_title,
        "semester": semester,
        "topicCode": topic_code,
        "topicTitle": block_title,
        "points": points,
        "practicalResult": practical_result,
        "sequenceInput": sequence_input,
        "sequenceOutput": sequence_output,
        "situation": situation,
        "goal": goal,
        "outcomes": outcomes,
        "sourceData": {"intro": COMMON_INTRO, "sections": source_sections},
        "tools": tools,
        "theoryCards": theory,
        "task": task,
        "stages": stages,
        "deliverables": deliverables,
        "evidence": evidence,
        "selfCheck": self_check,
        "professionalChoice": professional_choice,
        "wordRequirements": WORD_REQUIREMENTS,
        "lmsSteps": LMS_STEPS,
        "reportFile": report_file,
        "recommendedFileName": f"Фамилия_Группа_МДК0602_С{semester}_ЛР{semester_lab_number:02d}.docx",
    }


