def main() -> None:
    if len(LABS) != 12:
        raise RuntimeError("Ожидалось 12 лабораторных работ")
    semester_points = {
        semester: sum(lab["points"] for lab in LABS if lab["semester"] == semester)
        for semester in (7, 8)
    }
    if semester_points != {7: 50, 8: 50}:
        raise RuntimeError(f"Неверное распределение баллов: {semester_points}")
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(json.dumps({"labs": LABS}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("OK: 12 лабораторных работ, 50 + 50 = 100 баллов")


if __name__ == "__main__":
    main()
